import { Plugin } from 'vite';

interface SSGPluginOptions {
    routes?: string[];
    /**
     * Timeout for route discovery and crawling (ms)
     * @default 60000
     */
    discoveryTimeout?: number;
    /**
     * Use Playwright instead of Puppeteer
     * @default false
     */
    usePlaywright?: boolean;
    /**
     * Automatically generate platform-specific config files (vercel.json, netlify.toml, etc.)
     * @default true
     */
    generatePlatformConfig?: boolean;
    /**
     * Enable automatic route crawling - plugin will navigate your app and discover all routes
     * @default true
     */
    autoCrawl?: boolean;
    /**
     * Maximum depth for route crawling
     * @default 3
     */
    crawlDepth?: number;
    /**
     * Patterns to exclude from crawling (regex strings)
     * @default ['/admin', '/login', '/auth']
     */
    excludePatterns?: string[];
    /**
     * Site URL for sitemap generation (e.g., 'https://example.com')
     * If not provided, sitemap will use relative URLs
     */
    siteUrl?: string;
    /**
     * Generate sitemap.xml
     * @default true
     */
    generateSitemap?: boolean;
    /**
     * Generate robots.txt
     * @default true
     */
    generateRobotsTxt?: boolean;
    /**
     * Custom robots.txt rules
     */
    robotsTxtOptions?: {
        policies?: Array<{
            userAgent: string;
            allow?: string[];
            disallow?: string[];
            crawlDelay?: number;
        }>;
        additionalSitemaps?: string[];
    };
    /**
     * Enable debug mode with verbose logging
     * Shows detailed timing, console logs, network requests, and error information
     * @default true
     */
    debug?: boolean;
    /**
     * Save failed page screenshots for debugging
     * Screenshots will be saved to dist/ssg-debug/
     * @default false
     */
    saveScreenshots?: boolean;
    /**
     * Skip SSG errors and continue build
     * When true, build will continue even if SSG fails
     * @default false
     */
    skipOnError?: boolean;
}

declare function viteSSG(options?: SSGPluginOptions): Plugin;

export { type SSGPluginOptions, viteSSG as default, viteSSG };
